struct rng_params {
    char *buf;
    size_t buf_len;
};

int main() {
    int fd;
    char *buffer;
    struct rng_params params;
    int ret;

    // Open the device
    printf("[*] Opening /dev/krypto device...\n");
    fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        printf("[-] Failed to open device: %s\n", strerror(errno));
        return -1;
    }
    printf("[+] Device opened successfully (fd=%d)\n", fd);

    // Allocate buffer for RNG output
    buffer = malloc(16);
    if (!buffer) {
        printf("[-] Failed to allocate buffer\n");
        close(fd);
        return -1;
    }
    memset(buffer, 0, 16);

    // Setup RNG params
    params.buf = buffer;
    params.buf_len = 16;

    // Make ioctl call
    printf("[*] Making ioctl call with KRYPTO_RNG_CMD...\n");
    ret = ioctl(fd, KRYPTO_RNG_CMD, &params);
    if (ret < 0) {
        printf("[-] ioctl failed: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return -1;
    }
    printf("[+] ioctl call successful\n");

    // Print received data
    printf("[+] Received random data:\n");
    for (int i = 0; i < 16; i++) {
        printf("%02x ", (unsigned char)buffer[i]);
    }
    printf("\n");

    // Cleanup
    free(buffer);
    close(fd);
    return 0;
}

